import React, { useState, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { SectionLabel, PillButton, TextInput, FieldDropdown, FieldDisplay } from './components/UIPrimitives';
import { MediaPreview } from './components/MediaPreview';
import { extractAudio } from './services/audioService';

export default function App() {
  const [lyrics, setLyrics] = useState('');
  const [genre, setGenre] = useState('Lo-fi');
  const [atmosphere, setAtmosphere] = useState('Dreamy');
  const [model, setModel] = useState('Omni Flash');
  const [isGenerating, setIsGenerating] = useState(false);
  const [videoResult, setVideoResult] = useState<{ base64: string; mimeType: string; mediaId: string } | null>(null);
  const [isExtracting, setIsExtracting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Inject Design System CSS
  useEffect(() => {
    const id = 'flow-design-system-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
      .dark-scrollbar::-webkit-scrollbar { width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', 'Google Sans', -apple-system, sans-serif; letter-spacing: 0.1px; }
      @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
      .shimmer { background: linear-gradient(90deg, #1a1a1a 25%, #2a2a2a 50%, #1a1a1a 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; }
    `;
    document.head.appendChild(style);
  }, []);

  const handleGenerate = async () => {
    if (!lyrics.trim()) {
      setError('Please enter some lyrics first.');
      return;
    }

    setError(null);
    setIsGenerating(true);
    setVideoResult(null);

    try {
      // Craft a prompt that encourages the model to generate a music-driven result
      const prompt = `A cinematic music video visualizing these lyrics: "${lyrics}". Style: ${genre}. Atmosphere: ${atmosphere}. The video should have a strong musical rhythm and high-quality audio track aligned with the lyrics.`;

      const result = await Flow.generate.video({
        prompt,
        modelDisplayName: model,
        aspectRatio: '16:9',
        durationSeconds: 10 // Omni Flash supports up to 10s
      });

      setVideoResult(result);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Generation failed. Please try again.');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDownloadAudio = async () => {
    if (!videoResult) return;
    setIsExtracting(true);
    try {
      const audioBase64 = await extractAudio(videoResult.base64, videoResult.mimeType);
      await Flow.download({
        base64: audioBase64,
        mimeType: 'audio/mp3',
        filename: `lyricflow_audio_${Date.now()}.mp3`
      });
    } catch (err) {
      setError('Failed to extract audio. This model might not have generated a sound track.');
    } finally {
      setIsExtracting(false);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] text-white overflow-hidden">
      {/* Left Panel: Controls */}
      <div className="w-[300px] h-full border-r border-[rgba(218,220,224,0.15)] flex flex-col p-[12px] gap-[24px]">
        <div className="flex flex-col gap-2">
          <SectionLabel>Lyrics</SectionLabel>
          <TextInput 
            value={lyrics} 
            onChange={setLyrics} 
            placeholder="Enter your lyrics or poem..." 
          />
        </div>

        <div className="flex flex-col gap-2">
          <SectionLabel>Musical Style</SectionLabel>
          <div className="flex flex-col gap-1.5">
            <FieldDropdown 
              label="Genre" 
              value={genre} 
              options={['Lo-fi', 'Cinematic', 'Rock', 'Pop', 'Ambient', 'Synthwave', 'Jazz']} 
              onChange={setGenre} 
            />
            <FieldDropdown 
              label="Atmosphere" 
              value={atmosphere} 
              options={['Dreamy', 'Energetic', 'Melancholic', 'Epic', 'Chill', 'Dark']} 
              onChange={setAtmosphere} 
            />
          </div>
        </div>

        <div className="flex flex-col gap-2">
          <SectionLabel>AI Model</SectionLabel>
          <FieldDropdown 
            label="Generator" 
            value={model} 
            options={['Omni Flash', 'Veo 3.1 - Lite', 'Veo 3.1 - Fast']} 
            onChange={setModel} 
          />
          <p className="text-[10px] text-[rgba(218,220,224,0.4)] px-2">
            Note: Audio generation depends on the model's creative interpretation of the lyrics.
          </p>
        </div>

        {error && (
          <div className="p-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-[11px] leading-relaxed">
            {error}
          </div>
        )}

        <div className="mt-auto pt-4 border-t border-[rgba(218,220,224,0.15)]">
          <PillButton 
            variant="solid" 
            onClick={handleGenerate} 
            disabled={isGenerating}
            icon={<span className="material-symbols-outlined text-[18px]">{isGenerating ? 'hourglass_empty' : 'music_note'}</span>}
          >
            {isGenerating ? 'Generating Music...' : 'Generate Video & Audio'}
          </PillButton>
        </div>
      </div>

      {/* Main View: Preview */}
      <div className="flex-1 h-full relative flex flex-col items-center justify-center p-8 bg-[#0a0a0a]">
        <MediaPreview 
          video={videoResult} 
          isGenerating={isGenerating} 
          isExtracting={isExtracting}
          onDownloadAudio={handleDownloadAudio}
        />

        {/* Floating Instructions if empty */}
        {!videoResult && !isGenerating && (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-center opacity-40 select-none">
            <span className="material-symbols-outlined text-[64px] mb-4">music_video</span>
            <h2 className="text-xl font-medium mb-2">LyricFlow</h2>
            <p className="text-sm max-w-[300px]">Enter your lyrics on the left to generate an AI music video and extract the audio track.</p>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[6px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] px-4 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] px-4 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] px-4 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export const TextInput: React.FC<{
  value: string; 
  onChange: (val: string) => void; 
  placeholder?: string;
}> = ({ value, onChange, placeholder }) => (
  <textarea 
    value={value} 
    onChange={(e) => onChange(e.target.value)} 
    placeholder={placeholder}
    className="border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full h-[120px] px-3 py-2.5 resize-none bg-transparent text-[11px] font-medium text-white placeholder-[rgba(218,220,224,0.4)] tracking-[0.1px] focus:outline-none transition-colors dark-scrollbar" 
  />
);

export const FieldDropdown: React.FC<{
  label: string; 
  value: string; 
  options: string[];
  onChange: (val: string) => void; 
  className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setIsOpen(false);
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, []);

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button 
        type="button" 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none"
      >
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-2xl backdrop-blur-md origin-top animate-dropdown">
          <div className="max-h-40 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button 
                key={opt} 
                type="button"
                className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}
              >
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export const FieldDisplay: React.FC<{ label: string; value: string; className?: string }> = ({ label, value, className = '' }) => (
  <div className={`border border-[#595959] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none ${className}`}>
    <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
    <div className="flex items-center">
      <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}</span>
    </div>
  </div>
);

import React from 'react';
import { PillButton } from './UIPrimitives';

interface MediaPreviewProps {
  video: { base64: string; mimeType: string } | null;
  isGenerating: boolean;
  isExtracting: boolean;
  onDownloadAudio: () => void;
}

export const MediaPreview: React.FC<MediaPreviewProps> = ({ 
  video, 
  isGenerating, 
  isExtracting, 
  onDownloadAudio 
}) => {
  if (isGenerating) {
    return (
      <div className="w-full max-w-[800px] aspect-video rounded-2xl overflow-hidden shimmer flex flex-col items-center justify-center border border-[rgba(218,220,224,0.1)]">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-white/20 border-t-white rounded-full animate-spin" />
          <p className="text-[12px] font-medium text-white/60 tracking-wider">COMPOSING SOUND & VISION...</p>
        </div>
      </div>
    );
  }

  if (!video) return null;

  return (
    <div className="w-full max-w-[800px] flex flex-col gap-6 animate-in fade-in zoom-in duration-500">
      <div className="aspect-video bg-black rounded-2xl overflow-hidden border border-[rgba(218,220,224,0.15)] shadow-2xl relative group">
        <video 
          src={`data:${video.mimeType};base64,${video.base64}`} 
          className="w-full h-full object-contain"
          controls
          autoPlay
        />
      </div>

      <div className="flex flex-wrap gap-3 justify-center">
        <PillButton 
          variant="outline" 
          onClick={onDownloadAudio}
          disabled={isExtracting}
          icon={<span className="material-symbols-outlined text-[18px]">{isExtracting ? 'sync' : 'audio_file'}</span>}
        >
          {isExtracting ? 'Extracting Audio...' : 'Download Audio Track'}
        </PillButton>

        <PillButton 
          variant="filled" 
          onClick={() => {
            const link = document.createElement('a');
            link.href = `data:${video.mimeType};base64,${video.video ? '' : video.base64}`;
            // We use Flow.download instead for better compliance
            import('flow-sdk').then(f => f.Flow.download({
              base64: video.base64,
              mimeType: video.mimeType,
              filename: `lyricflow_video_${Date.now()}.mp4`
            }));
          }}
          icon={<span className="material-symbols-outlined text-[18px]">movie</span>}
        >
          Download Video
        </PillButton>
      </div>
    </div>
  );
};

import { 
  Input, Output, Conversion, 
  Mp3OutputFormat, BufferTarget, BlobSource, ALL_FORMATS,
  canEncodeAudio
} from 'mediabunny';
import { registerMp3Encoder } from '@mediabunny/mp3-encoder';

let encodersInitialized = false;

async function initEncoders() {
  if (encodersInitialized) return;
  if (!(await canEncodeAudio('mp3'))) {
    registerMp3Encoder();
  }
  encodersInitialized = true;
}

/**
 * Extracts audio from a video base64 string and returns the audio as a base64 string.
 */
export async function extractAudio(videoBase64: string, mimeType: string): Promise<string> {
  await initEncoders();

  const binaryString = atob(videoBase64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  const videoBlob = new Blob([bytes], { type: mimeType });

  const input = new Input({ 
    source: new BlobSource(videoBlob), 
    formats: ALL_FORMATS 
  });

  const output = new Output({
    format: new Mp3OutputFormat(),
    target: new BufferTarget(),
  });

  const conversion = await Conversion.init({
    input,
    output,
    video: { discard: true }, // Discard video to extract only audio
    audio: { codec: 'mp3' }
  });

  if (!conversion.isValid) {
    throw new Error('Audio extraction not possible for this file.');
  }

  await conversion.execute();

  const audioBuffer = output.target.buffer!;

  // Convert ArrayBuffer to base64 safely
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64 = (reader.result as string).split(',')[1];
      resolve(base64);
    };
    reader.readAsDataURL(new Blob([audioBuffer], { type: 'audio/mp3' }));
  });
}
